  "TryInteractWithPlayer": {
    returnType: "static const u8 *",
    params: "struct CableClubPlayer *player",
    callsTo: ["GetInteractedLinkPlayerScript","GetLinkPlayerIdAt","GetLinkTrainerCardColor"],
    lineCount: 21,
    bodyC: "struct MapPosition otherPlayerPos;\n    u8 linkPlayerId;\n\n    if (player->movementMode != MOVEMENT_MODE_FREE && player->movementMode != MOVEMENT_MODE_SCRIPTED)\n        return FACING_NONE;\n\n    otherPlayerPos = player->pos;\n    otherPlayerPos.x += gDirectionToVectors[player->facing].x;\n    otherPlayerPos.y += gDirectionToVectors[player->facing].y;\n    otherPlayerPos.elevation = ELEVATION_TRANSITION;\n    linkPlayerId = GetLinkPlayerIdAt(otherPlayerPos.x, otherPlayerPos.y);\n\n    if (linkPlayerId != MAX_LINK_PLAYERS)\n    {\n        if (!player->isLocalPlayer)\n            return CableClub_EventScript_TooBusyToNotice;\n        else if (sPlayerLinkStates[linkPlayerId] != PLAYER_LINK_STATE_IDLE)\n            return CableClub_EventScript_TooBusyToNotice;\n        else if (!GetLinkTrainerCardColor(linkPlayerId))\n            return CableClub_EventScript_ReadTrainerCard;\n        else\n            return CableClub_EventScript_ReadTrainerCardColored;\n    }\n\n    return GetInteractedLinkPlayerScript(&otherPlayerPos, player->metatileBehavior, player->facing);",
  },
  "UpdateAllLinkPlayers": {
    returnType: "static void",
    params: "u16 *keys, s32 selfId",
    callsTo: ["GetDirectionForDpadKey","HandleLinkPlayerKeyInput","LoadCableClubPlayer","SetPlayerFacingDirection"],
    lineCount: 12,
    bodyC: "struct CableClubPlayer trainer;\n    s32 i;\n\n    for (i = 0; i < MAX_LINK_PLAYERS; i++)\n    {\n        u8 key = keys[i];\n        u16 setFacing = FACING_NONE;\n        LoadCableClubPlayer(i, selfId, &trainer);\n        HandleLinkPlayerKeyInput(i, key, &trainer, &setFacing);\n        if (sPlayerLinkStates[i] == PLAYER_LINK_STATE_IDLE)\n            setFacing = GetDirectionForDpadKey(key);\n        SetPlayerFacingDirection(i, setFacing);\n    }",
  },
  "UpdateAmbientCry": {
    returnType: "void",
    params: "s16 *state, u16 *delayCounter",
    callsTo: ["CalculatePlayerPartyCount","GetMonAbility","GetMonData","PlayAmbientCry","Random"],
    lineCount: 38,
    bodyC: "u8 i, monsCount, divBy;\n\n    switch (*state)\n    {\n    case AMB_CRY_INIT:\n         \n        if (sAmbientCrySpecies == SPECIES_NONE)\n            *state = AMB_CRY_IDLE;\n        else\n            *state = AMB_CRY_FIRST;\n        break;\n    case AMB_CRY_FIRST:\n         \n        *delayCounter = (Random() % 2400) + 1200;\n        *state = AMB_CRY_WAIT;\n        break;\n    case AMB_CRY_RESET:\n        divBy = 1;\n        monsCount = CalculatePlayerPartyCount();\n        for (i = 0; i < monsCount; i++)\n        {\n            if (!GetMonData(&gPlayerParty[i], MON_DATA_SANITY_IS_EGG)\n                && GetMonAbility(&gPlayerParty[0]) == ABILITY_SWARM)\n            {\n                divBy = 2;\n                break;\n            }\n        }\n         \n         \n        *delayCounter = ((Random() % 1200) + 1200) / divBy;\n        *state = AMB_CRY_WAIT;\n        break;\n    case AMB_CRY_WAIT:\n        if (--(*delayCounter) == 0)\n        {\n            PlayAmbientCry();\n            *state = AMB_CRY_RESET;\n        }\n        break;\n    case AMB_CRY_IDLE:\n         \n        break;\n    }",
  },
